// note: The text of a source file. A `.json` file holds a syntax tree (spec section 20.1); its canonical text is what the rest of the compiler reads, so diagnostics point into that text.
fn f_source_text(v_path: Rc<String>, v_file: i64, v_overrides: Rc<std::collections::BTreeMap<Rc<String>, Rc<String>>>) -> Rc<T_SourceText> {
    t_enter("stage1/main.tes:261:4 in function `source_text`");
    match &(t_map_get(&v_overrides.clone(), &v_path.clone())) {
        Some(t1) => { let v_changed = t1.clone(); return Rc::new(T_SourceText { f_text: v_changed, f_diagnostics: Rc::new(Vec::<Rc<T_source__Diagnostic>>::new()) }) }
        None => { {
        } }
    };
    let v_text: Rc<String> = t_read_file(v_path.clone(), "stage1/main.tes:266:12 in function `source_text`");
    if (!f_source__ends_with_text(v_path.clone(), t_text(".json"))) {
        return Rc::new(T_SourceText { f_text: v_text, f_diagnostics: Rc::new(Vec::<Rc<T_source__Diagnostic>>::new()) })
    };
    let v_read: Rc<T_astjson__ReadFile> = f_astjson__read_tree(v_text.clone(), v_file.clone());
    if ((v_read.clone()).f_error.clone() != t_text("")) {
        return Rc::new(T_SourceText { f_text: t_text(""), f_diagnostics: Rc::new(vec![f_json_error(v_file, (v_read).f_error.clone())]) })
    };
    Rc::new(T_SourceText { f_text: f_printer__render_file((v_read.clone()).f_items.clone(), (v_read.clone()).f_comments.clone(), v_file), f_diagnostics: Rc::new(Vec::<Rc<T_source__Diagnostic>>::new()) })
}

