// note: The one candidate closest to `name` (one edit for short names, two for longer ones), or empty when there is none or a tie.
fn f_checker__closest(v_name: Rc<String>, v_candidates: Rc<Vec<Rc<String>>>) -> Rc<String> {
    t_enter("stage1/checker.tes:2927:4 in function `checker__closest`");
    let v_limit: i64 = if (t_list_length(&t_code_points(&v_name.clone())) <= 4i64) {
        1i64
    } else {
        2i64
    };
    let mut v_best: Rc<String> = t_text("");
    let mut v_best_distance: i64 = t_add(v_limit.clone(), 1i64, "stage1/checker.tes:2930:27 in function `checker__closest`");
    let mut v_tie: bool = false;
    for v_candidate in t_iter(v_candidates.clone()) {
        t_tick("stage1/checker.tes:2932:29 in function `checker__closest`");
        if ((v_candidate.clone() == v_name.clone()) || (v_candidate.clone() == v_best.clone())) {
            continue
        };
        let v_distance: i64 = f_checker__edit_distance(v_name.clone(), v_candidate.clone());
        if (v_distance.clone() < v_best_distance.clone()) {
            v_best = v_candidate.clone();
            v_best_distance = v_distance.clone();
            v_tie = false;
        } else if (v_distance.clone() == v_best_distance.clone()) {
            v_tie = true;
        }
    }
    if v_tie {
        t_text("")
    } else {
        v_best
    }
}

